TRACK_BY_ID = {track["id"]: track for track in TRACKS}
TRACK_BY_BOOK = {track["book"]: track for track in TRACKS}


def article_track(article):
    slug = article["slug"]
    if slug in {"call-center-automation-roi", "ai-contact-centers-roi"}:
        return TRACK_BY_ID["metrics"]
    if slug == "global-cx-local-operating-intelligence":
        return TRACK_BY_ID["quality"]
    if slug == "customer-effort-architecture-contact-centers":
        return TRACK_BY_ID["operations"]
    cluster = article.get("cluster", "")
    if cluster in {"sbc-contact-centers", "bpo-telecom-infrastructure"}:
        return TRACK_BY_ID["voice"]
    if cluster in {"international-market-entry", "ccaas-latam", "latam-nearshore-cx"}:
        return TRACK_BY_ID["sales"]
    return TRACK_BY_ID["ai"]
